    std::cout &lt;&lt; v.front() &lt;&lt; ' ' &lt;&lt; v.back() &lt;&lt; '\n'; // 10 50

    v[1] = 25;
    v.at(2) = 35;

    for (std::size_t i = 0; i &lt; v.size(); ++i) {
        std::cout &lt;&lt; v[i] &lt;&lt; ' ';                      // 10 25 35 40 50
    }
